/**
 * Condition C2 (error preservation): the native planner may only fold a join to an empty relation when the discarded
 * operand cannot hide a query-fatal error such as a failed non-SILENT SERVICE call.
 */
@ResourceLock(Resources.SYSTEM_PROPERTIES)
class LmdbNativeFatalErrorPreservationTest {

	private static final String SVC = "SERVICE <http://localhost:1/unreachable> { ?s ?p ?o }";
	private static final String SILENT_SVC = "SERVICE SILENT <http://localhost:1/unreachable> { ?s ?p ?o }";
	private static final String EX = "http://example.com/";

	static Stream<Arguments> cases() {
		Stream.Builder<Arguments> cases = Stream.builder();
		for (boolean experimental : new boolean[] { false, true }) {
			cases.add(Arguments.of(experimental, "emptyValuesThenService", "SELECT * { VALUES ?k { } " + SVC + " }"));
			cases.add(Arguments.of(experimental, "emptyValuesThenServiceInConstantGraph",
					"SELECT * { VALUES ?k { } GRAPH <" + EX + "g1> { " + SVC + " } }"));
			cases.add(Arguments.of(experimental, "unmatchedPatternThenServiceInGraph",
					"SELECT * { ?x <" + EX + "nonexistent> ?y GRAPH ?g { " + SVC + " } }"));
			cases.add(Arguments.of(experimental, "emptyValuesThenServiceInVariableGraph",
					"SELECT * { VALUES ?k { } GRAPH ?g { " + SVC + " } }"));
			cases.add(Arguments.of(experimental, "serviceThenEmptyValues", "SELECT * { " + SVC + " VALUES ?k { } }"));
		}
		return cases.build();
	}

	@TempDir
	File directory;
	private SailRepository repository;

	@AfterEach
	void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
	}

	@ParameterizedTest(name = "experimental={0} {1}")
	@MethodSource("cases")
	void nonSilentServiceFailureIsNotSuppressedByEmptyJoinOperand(boolean experimental, String name, String query) {
		RepositoryConnection connection = open(experimental);
		assertThatThrownBy(() -> QueryResults.asList(connection.prepareTupleQuery(query).evaluate()))
				.as(name)
				.isInstanceOf(QueryEvaluationException.class);
		connection.close();
	}

	@ParameterizedTest(name = "experimental={0} {1} SILENT")
	@MethodSource("cases")
	void silentServiceFailureYieldsNoError(boolean experimental, String name, String query) {
		RepositoryConnection connection = open(experimental);
		String silent = query.replace(SVC, SILENT_SVC);
		assertThat(QueryResults.asList(connection.prepareTupleQuery(silent).evaluate())).as(name).isEmpty();
		connection.close();
	}

	private RepositoryConnection open(boolean experimental) {
		LmdbStore store = new LmdbStore(directory, new LmdbStoreConfig("spoc,posc,ospc")
				.setNativeEvaluationEnabled(true)
				.setSketchEstimatorEnabled(false));
		store.setExperimentalQueryOptimizations(experimental);
		repository = new SailRepository(store);
		repository.init();
		IRI g1 = repository.getValueFactory().createIRI(EX + "g1");
		RepositoryConnection connection = repository.getConnection();
		connection.add(repository.getValueFactory().createIRI(EX + "a"),
				repository.getValueFactory().createIRI(EX + "p"), repository.getValueFactory().createIRI(EX + "o"),
				g1);
		return connection;
	}
}
